    },
    {
      "claim": "L5 records are transporter/efflux mechanism data only and none reports an oral F value. Strong Caco-2 efflux (ER 15–17), low Papp/efflux for mefloquine, and P-gp/ABCG2 substrate status in reference compounds are low-transfer and cannot establish F < 20% for the query.",
      "card_ids": ["C85", "C86", "C87", "C88", "C89", "C90", "C91", "C92", "C93", "C94", "C95", "C96"]
    },
    {
      "claim": "The only quantitative sub-20% F record (GSK269984A mouse ~14%) is low-transfer and contradicted by human L1 F 95%/>94%, so it does not support a low prediction.",
      "card_ids": ["C58", "C02", "C32"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C85", "C86", "C87", "C88", "C89", "C90", "C91", "C92", "C93", "C94", "C95", "C96"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule.",
    "No query-specific solubility, dissolution, permeability, efflux, or intestinal metabolism data; L4/L5 records are for reference molecules.",
    "Formulation and dose for the query are unspecified; solubility and dissolution can be formulation-dependent.",
    "First-pass metabolism, N-oxide reduction, efflux transport, and intestinal metabolism are uncharacterized for the query.",
    "Structural transfer from reference molecules is qualitative; no numeric similarity score is supplied.",
    "No affirmative threshold-relevant evidence supports F < 20% for the query."
  ],
  "decision_summary": "L5 efflux/transport records are mechanistic, low-transfer, and contain no F values; they do not overturn the high prediction supported by direct human F values for lipophilic, poorly soluble reference molecules. Prediction remains high with moderate confidence."
}

